const json = pm.response.json();

pm.collectionVariables.set("user_id", json.id);

pm.test("Status deve ser 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Resposta deve retornar ID e refletir os dados enviados", function () {
    pm.expect(json).to.have.property("id");
    pm.expect(json.name).to.eql("Bruno Ramos");
    pm.expect(json.username).to.eql("brunolopes");
    pm.expect(json.email).to.eql("bruno@email.com");
});

pm.test("ID salvo deve corresponder ao ID retornado", function () {
    pm.expect(Number(pm.collectionVariables.get("user_id"))).to.eql(json.id);
});
